struct MovieTextureCache {
    SDL_Texture* texture = nullptr;
    SDL_Renderer* renderer = nullptr;
    int width = 0, height = 0;
    uint64_t stream_id = 0, decoded_frames = 0;
    ~MovieTextureCache() { SDL_DestroyTexture(texture); }

    SDL_Texture* update(SDL_Renderer* target, const MoviePlayback& movie) {
        if (renderer != target || width != movie.width() || height != movie.height()) {
            SDL_DestroyTexture(texture);
            texture = nullptr;
        }
        if (!texture) {
            renderer = target;
            width = movie.width(); height = movie.height();
            texture = SDL_CreateTexture(target, SDL_PIXELFORMAT_RGBA32,
                SDL_TEXTUREACCESS_STREAMING, width, height);
            stream_id = decoded_frames = 0;
        }
        const auto statistics = movie.statistics();
        if (texture && (stream_id != statistics.stream_id ||
                        decoded_frames != statistics.decoded_frames)) {
            if (SDL_UpdateTexture(texture, nullptr, movie.rgba().data(), width * 4) != 0)
                return nullptr;
            stream_id = statistics.stream_id;
            decoded_frames = statistics.decoded_frames;
        }
        return texture;
    }
};

